    template <typename T>
    void TryMakeIterable(auto &c)
    {

        using std::begin;
        using std::end;
        if constexpr (
            requires(T &t)
            {


                requires std::is_same_v<decltype(begin(t)), decltype(end(t))>;
            }
        )
        {
            if constexpr (std::is_lvalue_reference_v<decltype(*begin(std::declval<T &>()))>)
            {
                c.def(
                    +"__iter__",
                    +[](T &target)
                    {
                        return pybind11::make_iterator(begin(target), end(target));
                    },


                    pybind11::keep_alive<0, 1>()
                );
            }
            else
            {
                c.def(
                    +"__iter__",
                    +[](T &target)
                    {
                        return pybind11::make_iterator<pybind11::return_value_policy::copy>(begin(target), end(target));
                    },

                    pybind11::keep_alive<0, 1>()
                );
            }
        }
    }

    template <typename T>
    struct AllowAutomaticPrinting : std::true_type {};


    template <typename T>
    void TryMakePrintable(auto &c)
    {
        if constexpr (AllowAutomaticPrinting<T>::value)
        {
            if constexpr (requires(std::ostream &s, const T &t){s << t;})
            {
                static const std::string name = c.attr("__qualname__").template cast<std::string>();
                c.def(
                    +"__repr__",
                    +[](const T &t)
                    {
                        std::ostringstream ss;
                        ss << t;

                        return name + '(' + std::move(ss).str() + ')';
                    }
                );
            }
        }
    }



    template <typename T>
    concept IsContiguousSequence = requires(const T &t)
    {
        typename T::value_type;
        requires std::is_integral_v<std::remove_cvref_t<decltype(t.size())>>;
        requires std::is_same_v<std::remove_cvref_t<decltype(*t.data())>, typename T::value_type>;
    };


    template <typename T>
    void TryMakeSized(auto &c)
    {
        if constexpr (IsContiguousSequence<T>)
            c.def(+"__len__", +[](const T &t){return std::size_t(t.size());});
    }



    template <typename T>
    concept IsListConstructibleSequence =
        IsContiguousSequence<T> &&
        std::is_default_constructible_v<T> &&
        std::is_move_constructible_v<T> &&
        std::is_copy_constructible_v<typename T::value_type> &&

        std::is_constructible_v<T, std::initializer_list<typename T::value_type>> &&
        requires(T &t, const typename T::value_type &v){t.push_back(v);};

    template <typename T>
    void TryMakeListConvertible(auto &c)
    {
        if constexpr (IsListConstructibleSequence<T>)
        {
            c.def(
                pybind11::init(
                    [](const pybind11::list &list)
                    {
                        T ret;
                        for (pybind11::handle elem : list)
                            ret.push_back(elem.cast<typename T::value_type>());
                        return ret;
                    }
                ),

                pybind11::keep_alive<1, 2>()
            );

            pybind11::implicitly_convertible<pybind11::list, T>();
        }
    }

    template <typename T>
    void FinalizeClass(auto &c, TryAddFuncScopeState &scope_state)
    {
        TryMakeIterable<T>(c);
        TryMakePrintable<T>(c);
        TryMakeSized<T>(c);
        TryMakeListConvertible<T>(c);





        if (!scope_state.have_default_ctor)
        {
            if constexpr (std::default_initializable<T>)
                c.def(pybind11::init(+[]{return std::make_shared<T>();}), +"Implicit default constructor.");
        }
        if (!scope_state.have_copy_ctor)
        {
            if constexpr (pybind11::detail::is_copy_constructible<T>::value)
                c.def(pybind11::init(+[](const T &other){return std::make_shared<T>(other);}), +"Implicit copy constructor.");
        }
    }


